{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Cilomilast had a mean absolute oral bioavailability of 96% (92–102%) in healthy humans after a 10 mg oral solution vs IV infusion, demonstrating that a lipophilic dimethoxyphenyl-containing drug can be essentially completely bioavailable; this highly transferable human measurement supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Vernakalant, which shares the 3,4-dimethoxyphenyl and basic tertiary-amine features of the query, showed absolute oral bioavailability of 71±21% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Irbesartan had an absolute oral bioavailability of about 70% in patients, showing that a moderately large lipophilic drug with multiple aromatic and polar groups can be well absorbed; this supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "In cirrhotic liver patients, meptazinol absolute bioavailability was 27.9±5.3% after a 200 mg oral dose vs IV, crossing the 20% threshold despite low F in healthy subjects; this is the most condition-matched evidence and directly supports high F under cirrhosis.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "In healthy young male volunteers, meptazinol absolute F was only 4.4±0.9%, showing that extensive first-pass metabolism can cause low F in the absence of cirrhosis; this is contradictory to high F but is not condition-matched and is superseded by the cirrhosis-specific C19 result.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Under cirrhosis, the most condition-specific evidence (meptazinol C19) shows F rising to 27.9%, above the 20% threshold, and multiple highly transferable human absolute-F measurements (cilomilast, vernakalant, irbesartan) are consistently high. The query's lipophilic dimethoxyphenyl/basic-amine features align with these high-F analogues; therefore predict high.",
  "evidence_gaps": [
    "No direct pharmacokinetic data for the query molecule itself.",
    "No cirrhosis-specific data for close structural analogues with the cyclic disulfone ring.",
    "The effect of the 1,3-dithiane tetraoxide ring on absorption and first-pass metabolism is not directly covered by the evidence."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C36"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "cilomilast"
    },
    {
      "applicability": "high",
      "card_ids": ["C16"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "vernakalant"
    },
    {
      "applicability": "high",
      "card_ids": ["C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "irbesartan"
    },
    {
      "applicability": "high",
      "card_ids": ["C19"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "meptazinol"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C31"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "meptazinol"
    }
  ],
  "revision_action": "initial"
}

